def unique_elements_with_counts(list_a, list_b):
    """
    Returns unique elements that appear in both lists A and B along with their combined counts.
    """
    combined_counts = {}

    # Count elements in list_a
    for elem in list_a:
        if elem in combined_counts:
            combined_counts[elem] += 1
        else:
            combined_counts[elem] = 1

    # Count elements in list_b
    for elem in list_b:
        if elem in combined_counts:
            combined_counts[elem] += 1
        else:
            combined_counts[elem] = 1

    # Find unique elements appearing in both lists
    result = []
    for elem in combined_counts:
        if elem in list_a and elem in list_b:
            result.append((elem, combined_counts[elem]))

    return result

