    env_vars = {'TEST_VAR': 'test_value', 'SECOND_VAR': 'second_value'}
    for key in env_vars:
        if key in os.environ:
            del os.environ[key]

    # Create a temporary directory and test file
    temp_file_path = tmpdir.join("test_file.txt")
    with open(temp_file_path, 'wb') as f:
        f.write(b'A' * (2 * 1024 * 1024 * 1024 + 1))  # Write more than 2 GiB of data

    manage_env_and_large_file(env_vars, str(temp_file_path))

    # Verify environment variables are set correctly
    for key, value in env_vars.items():
        assert os.environ[key] == value

    # Verify output when file is less than 2 GiB
    small_file_path = tmpdir.join("small_test_file.txt")
    with open(small_file_path, 'wb') as f:
        f.write(b'A' * 1024)  # Write 1 KiB of data

