def delete_reoccurring_characters_optimized(string: str) -> str:
    """
    Returns a new string with all duplicate characters removed, retaining only the first occurrence of each character.
    """
    seen = set()
    result = []
    for char in string:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

