reference_solution:
def min_operations(initialState, finalState):
    if sorted(initialState) != sorted(finalState):
        return -1

    n = len(initialState)
    ops = 0
    j = n - 1

    for i in range(n - 1, -1, -1):
        if initialState[i] == finalState[j]:
            j -= 1
        else:
            ops += 1

    return ops

