def remove_duplicates(sorted_list):
    """
    Remove duplicates from a sorted list.

    :param sorted_list: List[int] - A sorted list of integers
    :return: List[int] - A new list with duplicates removed
    """
    if not sorted_list:
        return []

    unique_list = [sorted_list[0]]

    for elem in sorted_list[1:]:
        if elem != unique_list[-1]:
            unique_list.append(elem)

    return unique_list

def total_friend_connections(popularity, k):
    n = len(popularity)
    total_connections = 0

    for i in range(n):
        for j in range(i + 1, n):
            if abs(popularity[i] - popularity[j]) <= k:
                total_connections += 1

    return total_connections

