def rabin_karp_enhanced(pattern: str, text: str) -> int:
    """
    Finds the first occurrence of the pattern in the text using the Rabin-Karp algorithm.
    :param pattern: The substring to be searched.
    :param text: The text within which the pattern is to be searched.
    :return: The starting index of the first occurrence of the pattern in the text, or -1 if the pattern is not found.
    """
    if len(pattern) > len(text):
        return -1

    base = 256  # Number of characters in the input alphabet
    prime = 101  # A prime number to use for hashing

    pattern_length = len(pattern)
    text_length = len(text)

    pattern_hash = 0
    text_hash = 0
    h = 1

    for i in range(pattern_length - 1):
        h = (h * base) % prime

    for i in range(pattern_length):
        pattern_hash = (base * pattern_hash + ord(pattern[i])) % prime
        text_hash = (base * text_hash + ord(text[i])) % prime

    for i in range(text_length - pattern_length + 1):
        if pattern_hash == text_hash:
            if text[i:i + pattern_length] == pattern:
                return i

        if i < text_length - pattern_length:
            text_hash = (base * (text_hash - ord(text[i]) * h) + ord(text[i + pattern_length])) % prime

            if text_hash < 0:
                text_hash += prime

    return -1

