def character_frequencies(s):
    """
    Returns a tuple containing:
    - A dictionary with the frequencies of each character in the string
    - A list of characters with the highest frequency in sorted order
    """
    frequencies = {}
    for char in s:
        if char != ' ':  # Ignore spaces
            if char in frequencies:
                frequencies[char] += 1
            else:
                frequencies[char] = 1

    if not frequencies:
        return frequencies, []

    max_freq = max(frequencies.values())
    max_chars = [char for char, count in frequencies.items() if count == max_freq]

    return frequencies, sorted(max_chars)

