def three_sum(nums, target):
    """
    Returns a list of unique triplets in the list which gives the sum of zero when added.
    :param nums: List[int] - list of integers
    :param target: int - the target sum, usually zero for this problem
    :return: List[List[int]] - list of unique triplets
    """
    nums.sort()
    res = []

    for i in range(len(nums) - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue # skip same element to avoid duplicate triplets
        l, r = i + 1, len(nums) - 1
        while l < r:
            sum = nums[i] + nums[l] + nums[r]
            if sum == target:
                res.append([nums[i], nums[l], nums[r]])
                while l < r and nums[l] == nums[l + 1]:
                    l += 1
                while l < r and nums[r] == nums[r - 1]:
                    r -= 1
                l += 1
                r -= 1
            elif sum < target:
                l += 1
            else:
                r -= 1

    return res

