def group_by_first_char(strings):
    """
    Groups strings by their first character.

    :param strings: List of strings
    :return: Dictionary with first characters as keys and lists of strings as values
    """
    result = {}
    for string in strings:
        first_char = string[0]
        if first_char not in result:
            result[first_char] = []
        result[first_char].append(string)
    return result

