from typing import List

def optimized_exchange_sort(arr: List[int]) -> List[int]:
    """
    Sorts the array using an optimized version of exchange sort with early termination check.
    """
    n = len(arr)
    for i in range(n - 1):
        swapped = False
        for j in range(n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr

