def tuples_to_dict(tuples_list):
    """
    Converts a list of tuples into a dictionary where the keys are the first elements of the tuples
    and the values are lists containing all the corresponding values from the tuples.

    Parameters:
    tuples_list (list of tuples): The input list of tuples.

    Returns:
    dict: A dictionary with unique keys and list of corresponding values.
    """
    result = {}
    for key, value in tuples_list:
        if key in result:
            result[key].append(value)
        else:
            result[key] = [value]
    return result

