def checkerboard_pattern(n):
    """
    Generates a checkerboard pattern of size n x n using '#' and ' ' starting with '#'.

    Parameters:
    n : int : the size of the checkerboard (should be even and >= 4)

    Returns:
    str : a string representing the checkerboard pattern with rows separated by '\n'
    """
    pattern = ""
    for i in range(n):
        row = ""
        for j in range(n):
            if (i + j) % 2 == 0:
                row += "#"
            else:
                row += " "
        pattern += row + "\n"
    return pattern.strip()

