def remove_excessive_characters(s):
    """
    Remove the minimum number of characters from the string so that every letter appears at most twice.
    """
    from collections import Counter

    count = Counter(s)
    result = []

    # Create a temporary dictionary to keep track of occurrences of each letter in the result
    temp_count = {char: 0 for char in count}

    for char in s:
        if temp_count[char] < 2:
            result.append(char)
            temp_count[char] += 1

    return ''.join(result)

