def count_words(s):
    """
    Count the occurrences of each word in a given string.

    Parameters:
    s (str): The input string containing words separated by spaces.

    Returns:
    dict: A dictionary with words as keys and their respective counts as values.
    """
    word_list = s.split()
    word_count = {}

    for word in word_list:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1

    return word_count

def can_split_into_pairs(arr, m):
    """
    Returns True if the given array can be split into pairs such that the sum of each pair equals m, 
    otherwise returns False.
    """
    from collections import Counter

    if len(arr) % 2 != 0:
        return False

    count = Counter(arr)

    for num in arr:
        if count[num] == 0:
            continue

        complement = m - num
        if count[complement] > 0:
            count[num] -= 1
            count[complement] -= 1
        else:
            return False

    return True

